def find_changed_pairs(inputs, outputs):
    """Find pairs where input differs from output"""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Simple approach: find first differing position and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            # Insertion case
            return ("", s_out[len(s_in):], len(s_in))
        else:
            # Deletion case  
            return (s_in[len(s_out):], "", len(s_out))

    # Find what to replace
    old_sub = ""
    new_sub = ""

    # Look for substring match
    for length in range(1, min(4, len(s_in) - pos + 1)):  # Max 3 chars
        if pos + length <= len(s_in):
            old_sub = s_in[pos:pos+length]
            if pos + length <= len(s_out):
                new_sub = s_out[pos:pos+length]
                if old_sub == new_sub:
                    continue  # Same, keep looking
                else:
                    return (old_sub, new_sub, pos)

    # Default to single character replacement
    return (s_in[pos], s_out[pos], pos)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a changed pair"""
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return most specific to most general
    candidates = []

    # Most specific: exact substring match
    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))

    # General patterns that could work
    # For example, if we see "e" -> "f", we might want to try "e" -> "f"
    # But let's be more systematic

    # Try different lengths for pattern
    if old_sub and len(old_sub) > 1:
        # Try shorter patterns
        for i in range(1, len(old_sub)):
            candidates.append((old_sub[:i], new_sub[:i] if len(new_sub) >= i else new_sub))

    # Also consider whole string if it's short enough
    if len(s_in) <= 3:
        candidates.append((s_in, s_out))

    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings"""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules transform inputs to outputs"""
    transformed = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(transformed, outputs) if i == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find cases where rules modify strings that should stay unchanged"""
    transformed = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, trans) in enumerate(zip(inputs, outputs, transformed)):
        if inp != outp and inp == trans:
            # Rule didn't change anything, but it should have
            pass
        elif inp != outp and trans != outp:
            # Rule over-applied - changed something that shouldn't change
            over_apps.append((i, inp, trans))
    return over_apps

def simulate_rule_chain(s, rules):
    """Show step by step what happens with a string through rules"""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'rule': f"replace('{pattern}', '{replacement}')",
            'before': prev,
            'after': current
        })
    return trace

def build_proxy_rules(pattern, replacement, proxy="__X__"):
    """Build proxy rules to prevent counterfeeding"""
    pre_rule = (pattern, proxy)
    post_rule = (proxy, replacement)
    return (pre_rule, post_rule)

