outputs = ['xdi', 'kfxbii', 'gkfxbkxfxb', 'gbdxhfxb', 'adffxbi']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, inp, outp in changed:
    print(f"  {idx}: '{inp}' -> '{outp}'")

